import React from 'react';
import { useMobileDetection } from '../hooks/useMobileDetection';

const HEADER_HEIGHT = 64; // px

const ScarewareHeader: React.FC = () => {
  const { isMobile } = useMobileDetection();
  if (!isMobile) return null;
  return (
    <div style={{
      width: '100vw',
      position: 'fixed',
      top: 0,
      left: 0,
      background: 'linear-gradient(90deg, #007bff 0%, #00a651 100%)',
      color: 'white',
      padding: '1rem 0.5rem',
      textAlign: 'center',
      fontWeight: 700,
      fontSize: '1.2rem',
      letterSpacing: '0.02em',
      boxShadow: '0 2px 8px rgba(0,0,0,0.08)',
      zIndex: 10001,
      borderBottomLeftRadius: 12,
      borderBottomRightRadius: 12,
      pointerEvents: 'auto',
      minHeight: HEADER_HEIGHT,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
    }}>
      <span>Scareware Simulation Controls</span>
      {/* Placeholder for future controls or info */}
    </div>
  );
};

export default ScarewareHeader;
